function plan({state,user1,user2,name1,name2}){
  const pairs=[[user1,name1],[user2,name2]];
  if(pairs.some(([a,b])=>typeof a!=='string'||!a.trim()||typeof b!=='string'||!b.trim()||a.startsWith('YOUR_')||b.startsWith('YOUR_'))||user1===user2||name1===name2)throw Error('Configure two distinct Notion user IDs and Slack names');
  if(!Array.isArray(state?.users)||!Array.isArray(state?.tasks))throw Error('Incomplete read state');
  const users=pairs.map(([,name])=>{const matches=state.users.filter(u=>!u.isDeleted&&u.realName===name);if(matches.length!==1||!matches[0].userId)throw Error('Slack name must identify exactly one user');return matches[0].userId});
  const out=[];
  for(const page of state.tasks){
    const p=page.properties;if(!p||typeof p!=='object')throw Error('Missing task properties');
    const status=p.Status?.status?.name??p.Status?.select?.name;if(typeof status!=='string')throw Error('Missing Status');if(status==='Done')continue;
    const title=p.Task?.title;if(!Array.isArray(title))throw Error('Missing Task title');const task=title.map(x=>x.plain_text??x.text?.content??'').join('');if(!task)throw Error('Empty task title');
    const people=p['Notion User']?.people;if(!Array.isArray(people)||people.length>=25)throw Error('Missing or possibly truncated Notion User people');
    const ids=people.map(u=>{if(typeof u.id!=='string'||!u.id)throw Error('Assignee ID unavailable');return u.id});
    const due=p.Due?.date?.start;if(typeof due!=='string'||!due)throw Error('Missing task due date');
    const i=pairs.findIndex(([id])=>ids.includes(id));if(i>=0)out.push({channelId:users[i],text:'# TO DO\n☑️ '+task+' (Due: '+due+')'});
  }
  return {items:out};
}

const rawTasks=$('Read tasks').all().map(x=>x.json),rawUsers=$input.all().map(x=>x.json);const nonempty=x=>Object.keys(x).length>0;const tasks=rawTasks.filter(nonempty),slack=rawUsers.filter(nonempty);if(tasks.some(x=>x.object!=='page')||slack.some(x=>!x.id))throw Error('Invalid source response');const users=slack.map(x=>({userId:x.id,realName:x.profile?.real_name,isDeleted:x.deleted}));const r=plan({state:{tasks,users},user1:'YOUR_NOTION_USER_ID_1',user2:'YOUR_NOTION_USER_ID_2',name1:'YOUR_SLACK_FULL_NAME_1',name2:'YOUR_SLACK_FULL_NAME_2'});return r.items.map(x=>({json:x}));
